// Maple Street in daylight: asphalt streets, pale kerbs and sidewalks, a dithered lawn green with tufts, wood-plank floors inside houses.
// House rectangles come from S.floors42 (written once at reset): two per vec4, each packed as (corner+96)*32+size in whole metres.
fn floorAt42(p:vec2f)->bool {for(var k=0u;k<29u;k++){let f=S.floors42[k];if(f.x==0.0){break;}for(var h=0u;h<2u;h++){let a=select(f.x,f.z,h==1u);let b=select(f.y,f.w,h==1u);if(a==0.0){continue;}let x0=floor(a/32.0)-96.0;let z0=floor(b/32.0)-96.0;if(p.x>x0&&p.x<x0+a-(x0+96.0)*32.0&&p.y>z0&&p.y<z0+b-(z0+96.0)*32.0){return true;}}}return false;}
fn suburb42(p:vec2f,edge:f32,noise:f32,top:f32,own:vec3f)->vec3f {
 if(top>.05){return own;}
 let t=floor(p*4.0);let dither=f32((u32(abs(t.x+400.0))+u32(abs(t.y+400.0)))%2u);
 if(floorAt42(p)){let plank=fract(p.x*2.0);let seam=1.0-smoothstep(0.0,.06,min(plank,1.0-plank));return mix(vec3f(.66,.45,.27),vec3f(.58,.38,.22),dither*.5+noise*.3)*(1.0-seam*.35);}
 if(edge<0.0){return vec3f(.17,.18,.21)*(.92+noise*.16);}
 if(edge<.18){return vec3f(.70,.69,.64);}
 if(edge<1.7){let s=abs(fract(p+.5)-.5);let seam=1.0-smoothstep(0.0,.04,min(s.x,s.y));return vec3f(.60,.60,.56)*(.95+noise*.08)*(1.0-seam*.18);}
 let tuft=step(.93,rnd(u32(abs(t.x+500.0))*911u+u32(abs(t.y+500.0))*3571u));
 return mix(mix(vec3f(.085,.24,.12),vec3f(.10,.28,.14),dither),vec3f(.055,.17,.08),tuft*.8)*(.96+noise*.08);
}
