// House floors for the daylight ground shader (S.floors42 at float 3980): two rectangles per vec4, (corner+96)*32+size, whole metres.
function packFloors42(st,buildings){let k=0;for(const b of buildings){if(k>=58)break;const x0=Math.round(b.x),z0=Math.round(b.z),w=Math.round(b.w),d=Math.round(b.d);if(w<1||d<1||w>31||d>31||x0<-96||z0<-96)continue;const o=3980+(k>>1)*4+(k&1)*2;st[o]=(x0+96)*32+w;st[o+1]=(z0+96)*32+d;k++;}return k;}
